target.css:
:root {
  --ink: #173c45;
  --seafoam: #ccece5;
  --coral: #ef765e;
}

.tidal-pass {
  width: 440px;
  padding: 16px;
  border: 2px solid var(--ink);
  border-radius: 18px;
  background: var(--seafoam);
  color: var(--ink);
}

.pass-header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.pass-icon {
  display: grid;
  width: 46px;
  height: 46px;
  place-items: center;
  border-radius: 14px;
  background: var(--coral);
  font-size: 26px;
}

.pass-copy p,
.pass-copy h2,
.pass-details p {
  margin: 0;
}

.pass-copy p,
.detail strong {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
}

.pass-copy h2 {
  font-size: 21px;
  line-height: 1.2;
}

.pass-details {
  display: flex;
  gap: 10px;
  margin: 15px 0;
}

.detail {
  flex: 1;
  padding: 9px 10px;
  border: 1px solid var(--ink);
  border-radius: 9px;
  font-size: 14px;
}

.detail strong {
  display: block;
  margin-bottom: 3px;
}

.status {
  display: inline-block;
  padding: 6px 10px;
  border-radius: 999px;
  background: var(--ink);
  color: var(--seafoam);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
}

